// ES7 Demonstration: Array.prototype.includes() Method
export function evaluateEs7(items = [1, 2, NaN, 4]) {
  const hasNan = items.includes(NaN);
  const powerResult = 2 ** 4; // 16
  return { hasNan, powerResult, feature: 'Array.prototype.includes() Method' };
}

